import sys


def digital_root(n):
    if n < 10:
        return n
    s = 0
    m = n
    while m > 0:
        s += m % 10
        m //= 10
    return digital_root(s)


def main():
    sys.setrecursionlimit(100000)

    n = int(sys.stdin.read().split()[0])
    print(digital_root(n))


