import sys


def binary_search_recursive(values, x, lo=0, hi=None):
    if hi is None:
        hi = len(values) - 1
    if lo > hi:
        return -1
    mid = (lo + hi) // 2
    if values[mid] == x:
        return mid
    if values[mid] < x:
        return binary_search_recursive(values, x, mid + 1, hi)
    return binary_search_recursive(values, x, lo, mid - 1)


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    x = int(data[1 + n])
    print(binary_search_recursive(values, x))


main()

